Parameters

viewof preset = Inputs.select(
  [
    "Random",
    "Correlated (similarity in rankings across faculty/students)",
    "Anti-correlated (non-similarity in rankings across family/students) ",
    "Mutual (faculty prefer students who prefer them)"
  ],
  {label: "Ranking preset", value: "Random"}
)







viewof correlation = Inputs.range(
  [0, 1],
  {label: "Preference agreement (ρ)", step: 0.05, value: 0.7}
)







viewof proposerSide = Inputs.radio(
  ["Students", "Faculty"],
  {label: "Proposing side", value: "Faculty"}
)







viewof teachingFall = Inputs.select(
  ["A", "B", "C", "D", "E", "F", "G", "H", "—"],
  {label: "Fall teaching", value: "A"}
)







viewof teachingSpring = Inputs.select(
  ["A", "B", "C", "D", "E", "F", "G", "H", "—"],
  {label: "Spring teaching", value: "B"}
)







viewof labFall = Inputs.select(
  ["A", "B", "C", "D", "E", "F", "G", "H", "—"],
  {label: "Fall lab manager", value: "C"}
)







viewof labSpring = Inputs.select(
  ["A", "B", "C", "D", "E", "F", "G", "H", "—"],
  {label: "Spring lab manager", value: "D"}
)







viewof regenClick = Inputs.button("Regenerate", {label: " "})







nFaculty = 12







nStudents = 8







studentNames = ["A","B","C","D","E","F","G","H"]







semesters = ["Fall", "Spring"]







// Reactive: each role selector contributes a (student, semester) block.
// Same student picked twice in one semester is fine — both their slots
// are blocked once.
blocks = {
  const result = {};
  const add = (student, sem) =&gt; {
    if (student === "—") return;
    if (!result[student]) result[student] = [];
    if (!result[student].includes(sem)) result[student].push(sem);
  };
  add(teachingFall, "Fall");
  add(teachingSpring, "Spring");
  add(labFall, "Fall");
  add(labSpring, "Spring");
  return result;
}







// blockReason[student][semester] -&gt; human-readable role label.
blockReason = {
  const result = {};
  const add = (student, sem, reason) =&gt; {
    if (student === "—") return;
    if (!result[student]) result[student] = {};
    result[student][sem] = result[student][sem]
      ? `${result[student][sem]} + ${reason}`
      : reason;
  };
  add(teachingFall, "Fall", "teaching");
  add(teachingSpring, "Spring", "teaching");
  add(labFall, "Fall", "lab manager");
  add(labSpring, "Spring", "lab manager");
  return result;
}







eligibleStudents = (semester) =&gt; studentNames
  .map((name, i) =&gt; ({name, i}))
  .filter(({name}) =&gt; !(blocks[name] && blocks[name].includes(semester)))
  .map(({i}) =&gt; i)







// Seed re-rolls only when Regenerate is clicked. Preset / correlation
// changes reuse the same seed so results are deterministic per seed.
seed = {
  regenClick;
  return Math.floor(Math.random() * 1e9);
}







// Generate initial preferences: 12 faculty × 8 students, 8 students × 12 faculty.
initialPrefs = {
  const lcg = d3.randomLcg(seed / 1e9);
  const r = {
    uniform: lcg,
    normal: d3.randomNormal.source(lcg)(0, 1)
  };
  const mode = preset;
  const rho = correlation;

  const shuffle = (arr) =&gt; {
    const a = [...arr];
    for (let i = a.length - 1; i &gt; 0; i--) {
      const j = Math.floor(r.uniform() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  };
  const studentRange = Array.from({length: nStudents}, (_, i) =&gt; i);
  const facultyRange = Array.from({length: nFaculty}, (_, i) =&gt; i);

  const studentQuality = Array.from({length: nStudents}, () =&gt; r.normal());
  const facultyQuality = Array.from({length: nFaculty}, () =&gt; r.normal());

  const rankBy = (range, scores) =&gt;
    range.slice().sort((a, b) =&gt; scores[b] - scores[a]);

  let faculty, students;
  if (mode === "Random") {
    faculty = Array.from({length: nFaculty}, () =&gt; shuffle(studentRange));
    students = Array.from({length: nStudents}, () =&gt; shuffle(facultyRange));
  } else if (mode.startsWith("Mutual")) {
    // Each (faculty, student) pair shares a latent "fit" score. Both
    // sides rank by that same score plus per-evaluation noise — so a
    // faculty's ranking of S correlates with S's ranking of that
    // faculty. ρ → 1: rankings near-perfectly mutual; ρ → 0: random.
    const noiseSd = Math.max(0.01, Math.sqrt(1 - rho * rho) / Math.max(rho, 0.01));
    const fit = Array.from({length: nFaculty}, () =&gt;
      Array.from({length: nStudents}, () =&gt; r.normal())
    );
    faculty = Array.from({length: nFaculty}, (_, f) =&gt; {
      const scores = studentRange.map((s) =&gt; fit[f][s] + noiseSd * r.normal());
      return rankBy(studentRange, scores);
    });
    students = Array.from({length: nStudents}, (_, s) =&gt; {
      const scores = facultyRange.map((f) =&gt; fit[f][s] + noiseSd * r.normal());
      return rankBy(facultyRange, scores);
    });
  } else {
    const sign = mode.startsWith("Anti-correlated") ? -1 : 1;
    const noiseSd = Math.max(0.01, Math.sqrt(1 - rho * rho) / Math.max(rho, 0.01));
    faculty = Array.from({length: nFaculty}, () =&gt; {
      const scores = studentQuality.map((q) =&gt; sign * q + noiseSd * r.normal());
      return rankBy(studentRange, scores);
    });
    students = Array.from({length: nStudents}, () =&gt; {
      const scores = facultyQuality.map((q) =&gt; sign * q + noiseSd * r.normal());
      return rankBy(facultyRange, scores);
    });
  }
  return {faculty, students};
}







// Build the draggable preference editor. Takes an initial ordering and
// label functions for panel headers and item labels; returns an element
// whose `.value` is the current (reactive) ordering.
function prefEditor(initial, panelLabel, itemLabel) {
  const container = htl.html`&lt;div class="pref-grid"&gt;&lt;/div&gt;`;
  container.style.setProperty("--cols", initial.length);
  const state = initial.map((row) =&gt; [...row]);

  const rankLabels = (list) =&gt; {
    [...list.children].forEach((li, i) =&gt; {
      const rankEl = li.querySelector(".rank");
      if (rankEl) rankEl.textContent = (i + 1) + ".";
    });
  };

  state.forEach((row, idx) =&gt; {
    const panel = htl.html`&lt;div class="pref-panel"&gt;
      &lt;div class="pref-header"&gt;${panelLabel(idx)}&lt;/div&gt;
      &lt;ol class="pref-list"&gt;&lt;/ol&gt;
    &lt;/div&gt;`;
    const list = panel.querySelector(".pref-list");
    row.forEach((otherIdx) =&gt; {
      const li = htl.html`&lt;li data-id="${otherIdx}"&gt;&lt;span class="rank"&gt;&lt;/span&gt;${itemLabel(otherIdx)}&lt;/li&gt;`;
      list.appendChild(li);
    });
    rankLabels(list);
    // eslint-disable-next-line no-undef
    new Sortable(list, {
      animation: 120,
      ghostClass: "sortable-ghost",
      chosenClass: "sortable-chosen",
      onEnd: () =&gt; {
        state[idx] = [...list.children].map((li) =&gt; +li.dataset.id);
        rankLabels(list);
        container.value = state.map((r) =&gt; [...r]);
        container.dispatchEvent(new Event("input", {bubbles: true}));
      }
    });
    container.appendChild(panel);
  });

  container.value = state.map((r) =&gt; [...r]);
  return container;
}







Faculty preferences over students
Each column gives one faculty member’s rank-order over the 8 students (top = most preferred). The same ranking is used for both semesters — students unavailable in a given semester are simply skipped in that semester’s match.

viewof facultyPrefs = prefEditor(
  initialPrefs.faculty,
  (i) =&gt; `F${i + 1}`,
  (j) =&gt; studentNames[j]
)








Student preferences over faculty
Each column gives one student’s rank-order over the 12 faculty (top = most preferred).

viewof studentPrefs = prefEditor(
  initialPrefs.students,
  (i) =&gt; studentNames[i],
  (j) =&gt; `F${j + 1}`
)

Resulting match

// Many-to-many deferred-acceptance Gale-Shapley supporting per-side
// capacities. Faculty have capacity 1 per semester; eligible students
// have capacity 2 per semester. Returns proposer- and receiver-side
// match arrays keyed by id.
function manyToManyGS(proposers, receivers, proposerPrefs, receiverPrefs, proposerCap, receiverCap) {
  const receiverRank = {};
  for (const r of receivers) {
    const rk = {};
    receiverPrefs[r].forEach((p, i) =&gt; { rk[p] = i; });
    receiverRank[r] = rk;
  }
  const nextProposalIdx = {};
  const proposerMatches = {};
  for (const p of proposers) {
    nextProposalIdx[p] = 0;
    proposerMatches[p] = [];
  }
  const receiverMatches = {};
  for (const r of receivers) receiverMatches[r] = [];

  const free = [...proposers];
  while (free.length) {
    const p = free.shift();
    if (proposerMatches[p].length &gt;= proposerCap[p]) continue;
    if (nextProposalIdx[p] &gt;= proposerPrefs[p].length) continue;
    const r = proposerPrefs[p][nextProposalIdx[p]++];

    if (receiverMatches[r].length &lt; receiverCap[r]) {
      receiverMatches[r].push(p);
      proposerMatches[p].push(r);
    } else {
      const worst = receiverMatches[r].reduce((acc, q) =&gt;
        receiverRank[r][q] &gt; receiverRank[r][acc] ? q : acc
      );
      if (receiverRank[r][p] &lt; receiverRank[r][worst]) {
        receiverMatches[r] = receiverMatches[r].filter((q) =&gt; q !== worst);
        proposerMatches[worst] = proposerMatches[worst].filter((x) =&gt; x !== r);
        receiverMatches[r].push(p);
        proposerMatches[p].push(r);
        if (proposerMatches[worst].length &lt; proposerCap[worst] &&
            nextProposalIdx[worst] &lt; proposerPrefs[worst].length) {
          free.push(worst);
        }
      }
    }

    if (proposerMatches[p].length &lt; proposerCap[p] &&
        nextProposalIdx[p] &lt; proposerPrefs[p].length) {
      free.push(p);
    }
  }
  return {proposerMatches, receiverMatches};
}







matching = {
  const studentsPropose = proposerSide === "Students";
  const facultyRange = Array.from({length: nFaculty}, (_, i) =&gt; i);
  const result = {};

  for (const sem of semesters) {
    const eligible = eligibleStudents(sem);
    const eligibleSet = new Set(eligible);
    // Faculty rankings are over all 8 students; per-semester we drop blocked ones.
    const facultyPrefsFiltered = facultyPrefs.map((row) =&gt;
      row.filter((s) =&gt; eligibleSet.has(s))
    );

    let proposers, receivers, proposerPrefs, receiverPrefs, proposerCap, receiverCap;
    if (studentsPropose) {
      proposers = eligible;
      receivers = facultyRange;
      proposerPrefs = {};
      proposerCap = {};
      eligible.forEach((s) =&gt; {
        proposerPrefs[s] = studentPrefs[s];
        proposerCap[s] = 2;
      });
      receiverPrefs = {};
      receiverCap = {};
      facultyRange.forEach((f) =&gt; {
        receiverPrefs[f] = facultyPrefsFiltered[f];
        receiverCap[f] = 1;
      });
    } else {
      proposers = facultyRange;
      receivers = eligible;
      proposerPrefs = {};
      proposerCap = {};
      facultyRange.forEach((f) =&gt; {
        proposerPrefs[f] = facultyPrefsFiltered[f];
        proposerCap[f] = 1;
      });
      receiverPrefs = {};
      receiverCap = {};
      eligible.forEach((s) =&gt; {
        receiverPrefs[s] = studentPrefs[s];
        receiverCap[s] = 2;
      });
    }

    const m = manyToManyGS(
      proposers, receivers, proposerPrefs, receiverPrefs, proposerCap, receiverCap
    );

    const facultyToStudent = {};
    if (studentsPropose) {
      for (const f of facultyRange) facultyToStudent[f] = m.receiverMatches[f][0];
    } else {
      for (const f of facultyRange) facultyToStudent[f] = m.proposerMatches[f][0];
    }

    const pairs = [];
    for (const f of facultyRange) {
      const s = facultyToStudent[f];
      if (s === undefined) continue;
      pairs.push({
        faculty: f,
        student: s,
        facultyRankOfStudent: facultyPrefs[f].indexOf(s) + 1,
        studentRankOfFaculty: studentPrefs[s].indexOf(f) + 1
      });
    }
    const avg = (arr) =&gt; (arr.length ? arr.reduce((a, b) =&gt; a + b, 0) / arr.length : 0);

    result[sem] = {
      facultyToStudent,
      eligible,
      pairs,
      avgFacultyRank: avg(pairs.map((p) =&gt; p.facultyRankOfStudent)),
      avgStudentRank: avg(pairs.map((p) =&gt; p.studentRankOfFaculty)),
      firstChoiceFaculty: pairs.filter((p) =&gt; p.facultyRankOfStudent === 1).length,
      firstChoiceStudents: pairs.filter((p) =&gt; p.studentRankOfFaculty === 1).length
    };
  }
  return result;
}







function bipartiteForSemester(semData, semName) {
  const width = 480;
  const facRowH = 30;
  const facCount = nFaculty;
  const eligible = semData.eligible;
  const stuCount = Math.max(eligible.length, 1);
  const totalH = facCount * facRowH;
  const height = totalH + 40;
  const leftX = 130;
  const rightX = width - 130;
  const topPad = 20;

  const facY = (i) =&gt; topPad + i * facRowH + facRowH / 2;
  const stuY = (j) =&gt; topPad + (j + 0.5) * (totalH / stuCount);

  const stuPos = {};
  eligible.forEach((s, j) =&gt; { stuPos[s] = j; });

  const svg = d3.create("svg")
    .attr("viewBox", `0 0 ${width} ${height}`)
    .attr("preserveAspectRatio", "xMidYMid meet")
    .style("width", "100%")
    .style("height", "auto")
    .style("max-width", `${width}px`)
    .style("font", "13px system-ui, sans-serif");

  svg.append("text").attr("x", leftX).attr("y", 14)
    .attr("text-anchor", "end").attr("font-weight", 600)
    .text(`${semName} — Faculty`);
  svg.append("text").attr("x", rightX).attr("y", 14)
    .attr("text-anchor", "start").attr("font-weight", 600)
    .text(`${semName} — Student`);

  for (let i = 0; i &lt; facCount; i++) {
    const y = facY(i);
    svg.append("circle").attr("cx", leftX).attr("cy", y).attr("r", 5).attr("fill", "#1e40af");
    svg.append("text").attr("x", leftX - 10).attr("y", y + 4)
      .attr("text-anchor", "end").text(`F${i + 1}`);
  }
  for (let j = 0; j &lt; stuCount; j++) {
    const y = stuY(j);
    svg.append("circle").attr("cx", rightX).attr("cy", y).attr("r", 5).attr("fill", "#166534");
    svg.append("text").attr("x", rightX + 10).attr("y", y + 4)
      .attr("text-anchor", "start").text(studentNames[eligible[j]]);
  }

  // Color by mean of normalized ranks across both sides:
  // 0 = both got top → green; 1 = both got worst → red.
  const edgeColor = (p) =&gt; {
    const facNorm = (p.facultyRankOfStudent - 1) / (nStudents - 1);
    const stuNorm = (p.studentRankOfFaculty - 1) / (nFaculty - 1);
    const t = (facNorm + stuNorm) / 2;
    return d3.interpolateRdYlGn(1 - t);
  };

  semData.pairs.forEach((p) =&gt; {
    const y1 = facY(p.faculty);
    const y2 = stuY(stuPos[p.student]);
    svg.append("line")
      .attr("x1", leftX + 6).attr("y1", y1)
      .attr("x2", rightX - 6).attr("y2", y2)
      .attr("stroke", edgeColor(p))
      .attr("stroke-width", 2);
  });

  return svg.node();
}







function matchTableForSem(semData) {
  const rows = semData.pairs
    .slice()
    .sort((a, b) =&gt; a.faculty - b.faculty)
    .map((p) =&gt; htl.html`&lt;tr&gt;
      &lt;td&gt;F${p.faculty + 1}&lt;/td&gt;
      &lt;td&gt;${studentNames[p.student]}&lt;/td&gt;
      &lt;td&gt;${p.facultyRankOfStudent}&lt;/td&gt;
      &lt;td&gt;${p.studentRankOfFaculty}&lt;/td&gt;
    &lt;/tr&gt;`);
  return htl.html`&lt;table class="match-table"&gt;
    &lt;thead&gt;
      &lt;tr&gt;&lt;th&gt;Faculty&lt;/th&gt;&lt;th&gt;Matched student&lt;/th&gt;&lt;th&gt;Faculty's rank of student (of ${nStudents})&lt;/th&gt;&lt;th&gt;Student's rank of faculty (of ${nFaculty})&lt;/th&gt;&lt;/tr&gt;
    &lt;/thead&gt;
    &lt;tbody&gt;${rows}&lt;/tbody&gt;
  &lt;/table&gt;`;
}









Fall

bipartiteForSemester(matching["Fall"], "Fall")









Spring

bipartiteForSemester(matching["Spring"], "Spring")










combinedStats = {
  const f = matching["Fall"];
  const s = matching["Spring"];
  return htl.html`&lt;table class="match-table" style="margin: 1rem auto;"&gt;
    &lt;thead&gt;
      &lt;tr&gt;&lt;th&gt;&lt;/th&gt;&lt;th&gt;Fall&lt;/th&gt;&lt;th&gt;Spring&lt;/th&gt;&lt;/tr&gt;
    &lt;/thead&gt;
    &lt;tbody&gt;
      &lt;tr&gt;
        &lt;td style="text-align:left"&gt;Avg rank of match (Faculty)&lt;/td&gt;
        &lt;td&gt;${f.avgFacultyRank.toFixed(2)}&lt;/td&gt;
        &lt;td&gt;${s.avgFacultyRank.toFixed(2)}&lt;/td&gt;
      &lt;/tr&gt;
      &lt;tr&gt;
        &lt;td style="text-align:left"&gt;Avg rank of match (Students)&lt;/td&gt;
        &lt;td&gt;${f.avgStudentRank.toFixed(2)}&lt;/td&gt;
        &lt;td&gt;${s.avgStudentRank.toFixed(2)}&lt;/td&gt;
      &lt;/tr&gt;
      &lt;tr&gt;
        &lt;td style="text-align:left"&gt;Faculty who got their 1st choice&lt;/td&gt;
        &lt;td&gt;${f.firstChoiceFaculty} / ${nFaculty}&lt;/td&gt;
        &lt;td&gt;${s.firstChoiceFaculty} / ${nFaculty}&lt;/td&gt;
      &lt;/tr&gt;
      &lt;tr&gt;
        &lt;td style="text-align:left"&gt;Students who got their 1st choice&lt;/td&gt;
        &lt;td&gt;${f.firstChoiceStudents} / ${nFaculty}&lt;/td&gt;
        &lt;td&gt;${s.firstChoiceStudents} / ${nFaculty}&lt;/td&gt;
      &lt;/tr&gt;
    &lt;/tbody&gt;
  &lt;/table&gt;`;
}









Fall matches

matchTableForSem(matching["Fall"])









Spring matches

matchTableForSem(matching["Spring"])










Per-student summary
Two slots per semester per student. Italicized cells are committed before matching (teaching or lab manager).

studentSummary = {
  const rowEls = studentNames.map((name, s) =&gt; {
    const cells = [htl.html`&lt;td&gt;&lt;strong&gt;${name}&lt;/strong&gt;&lt;/td&gt;`];
    for (const sem of semesters) {
      if (blocks[name] && blocks[name].includes(sem)) {
        cells.push(htl.html`&lt;td&gt;&lt;em&gt;${blockReason[name][sem]}&lt;/em&gt;&lt;/td&gt;`);
      } else {
        const facs = matching[sem].pairs
          .filter((p) =&gt; p.student === s)
          .map((p) =&gt; `F${p.faculty + 1}`)
          .join(", ");
        cells.push(htl.html`&lt;td&gt;${facs || "—"}&lt;/td&gt;`);
      }
    }
    return htl.html`&lt;tr&gt;${cells}&lt;/tr&gt;`;
  });
  return htl.html`&lt;table class="match-table"&gt;
    &lt;thead&gt;
      &lt;tr&gt;&lt;th&gt;Student&lt;/th&gt;&lt;th&gt;Fall&lt;/th&gt;&lt;th&gt;Spring&lt;/th&gt;&lt;/tr&gt;
    &lt;/thead&gt;
    &lt;tbody&gt;${rowEls}&lt;/tbody&gt;
  &lt;/table&gt;`;
}
